from s1_ui import add

# v141: the Maasai Mara's safari plane operators, flying guests from Nairobi (and Lake Victoria) to the Talek airstrip.
# Braces are filled in by the app: {n} people, {d} first day, {e} last day, {len} mornings, {p} price per head, {r} rival.
# Late planes: a storm over the Rift Valley (Grace), zebras on the strip (Rajesh), clouds over the lake (Peter).

CAST = {
 "grace": ("Captain Grace Wambui", "Grace", "グレース・ワンブイ機長", "グレース", "그레이스 왐부이 기장", "그레이스",
           ("Owner and chief pilot of Rift Valley Air Safaris", "Rift Valley Air Safaris sahibi ve baş pilotu",
            "Inhaberin und Chefpilotin von Rift Valley Air Safaris", "Dueña y piloto jefe de Rift Valley Air Safaris",
            "リフトバレー・エア・サファリズの代表兼機長", "리프트 밸리 에어 사파리스 대표 겸 수석 조종사")),
 "rajesh": ("Rajesh Mehta", "Rajesh", "ラジェッシュ・メータ", "ラジェッシュ", "라제시 메타", "라제시",
            ("Founder of Acacia Wings, Nairobi", "Acacia Wings kurucusu, Nairobi", "Gründer von Acacia Wings, Nairobi",
             "Fundador de Acacia Wings, Nairobi", "アカシア・ウィングス創業者（ナイロビ）", "아카시아 윙스 창업자, 나이로비")),
 "peter": ("Peter Otieno", "Peter", "ピーター・オティエノ", "ピーター", "피터 오티에노", "피터",
           ("Owner of Kilima Air, Kisumu", "Kilima Air sahibi, Kisumu", "Inhaber von Kilima Air, Kisumu",
            "Dueño de Kilima Air, Kisumu", "キリマ・エア代表（キスム）", "킬리마 에어 대표, 키수무")),
}
# The Turkish name keeps the rank: "Kaptan Grace Wambui".
for k, (name, short, ja, jaS, ko, koS, title) in CAST.items():
    tr = "Kaptan Grace Wambui" if k == "grace" else name
    de = "Kapitänin Grace Wambui" if k == "grace" else name
    es = "Capitana Grace Wambui" if k == "grace" else name
    add(f"ctr.{k}.name", name, tr, de, es, ja, ko)
    add(f"ctr.{k}.short", short, short, short, short, jaS, koS)
    add(f"ctr.{k}.title", *title)


def lines(owner, d):
    for line, t in d.items():
        add(f"ctr.{owner}.{line}", *t)


